package nl.juiced.guhs.feature.vadsrijk.ruiters;

import java.io.BufferedReader;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.List;
import java.util.Locale;

import javax.annotation.Nullable;

import net.minecraft.world.phys.Vec3;
import org.slf4j.Logger;

/**
 * U-RUITERS: every route of the riding guhs, read once from {@code data/guhs/vadsrijk_ruiters/routes.txt} on the classpath
 * (GENERATED by tools/vadsrijk/ruiters/routes.py from the real map tiles: rerun it when the zone-1/zone-3 map changes).
 * Zone 3: the riding spiral, the inner stair, Honingtak, three branch paths, the Pluimstal (stable + training oval), the ground ring
 * and two roads through the Wortelvelden. Zone 1: a courier Haven -> Zwamzoet and a rider on the forest road.
 */
public final class RuiterRoutes {
    private static final Logger LOG = com.mojang.logging.LogUtils.getLogger();
    public static final String BESTAND = "/data/guhs/vadsrijk_ruiters/routes.txt";
    @Nullable
    private static List<RuiterRoute> alle;

    private RuiterRoutes() {
    }

    public static synchronized List<RuiterRoute> alle() {
        if (alle == null) {
            alle = lees();
        }
        return alle;
    }

    @Nullable
    public static RuiterRoute van(String id) {
        for (RuiterRoute r : alle()) {
            if (r.id.equals(id)) {
                return r;
            }
        }
        return null;
    }

    private static List<RuiterRoute> lees() {
        List<RuiterRoute> uit = new ArrayList<>();
        try (InputStream in = RuiterRoutes.class.getResourceAsStream(BESTAND)) {
            if (in == null) {
                LOG.warn("[vadsrijk ruiters] {} is missing: no riding guhs", BESTAND);
                return List.of();
            }
            BufferedReader r = new BufferedReader(new InputStreamReader(in, StandardCharsets.UTF_8));
            String[] kop = null;
            List<Vec3> punten = new ArrayList<>();
            for (String regel; (regel = r.readLine()) != null;) {
                regel = regel.strip();
                if (regel.isEmpty() || regel.startsWith("#")) {
                    continue;
                }
                String[] d = regel.split("\\s+");
                if (d[0].equals("route")) {
                    voegToe(uit, kop, punten);
                    kop = d;
                    punten = new ArrayList<>();
                } else if (d.length == 3) {
                    punten.add(new Vec3(Double.parseDouble(d[0]), Double.parseDouble(d[1]), Double.parseDouble(d[2])));
                }
            }
            voegToe(uit, kop, punten);
        } catch (Exception e) {
            LOG.error("[vadsrijk ruiters] could not read {}", BESTAND, e);
        }
        return List.copyOf(uit);
    }

    private static void voegToe(List<RuiterRoute> uit, @Nullable String[] kop, List<Vec3> punten) {
        if (kop == null) {
            return;
        }
        try {
            uit.add(new RuiterRoute(kop[1], Integer.parseInt(kop[2]), RuiterRoute.Modus.valueOf(kop[3].toUpperCase(Locale.ROOT)),
                    Integer.parseInt(kop[4]), Double.parseDouble(kop[5]), punten));
        } catch (RuntimeException e) {
            LOG.warn("[vadsrijk ruiters] route skipped: {} ({})", String.join(" ", kop), e.getMessage());
        }
    }
}
